<template>
            
            <form @submit.prevent="submitEntry()">
                <div class="row">
                   <div class="col-md-3">
                          <label class="form-label">Select Machine/Vehicle</label>
                                            <Multiselect
  v-model="formData.asset"
  :options="assets"
  label="name"
  placeholder="Select an item"  
  :searchable="true" 
  :allow-empty="false"
/>         
                    </div>

                       <div class="col-md-2">
                          <label class="form-label">Enter Quantity</label>
                          <input class="form-control" type="number" step="any" placeholder="Qty Issued" v-model="formData.quantity">
                        </div>

                        <div class="col-md-2">
                          <label class="form-label">Date</label>
                          <input class="form-control" type="date" v-model="formData.date">
                        </div>
                        
                        <div class="col-md-5">
                          <label class="form-label">Description</label>
                          <input class="form-control" type="text" v-model="formData.description" placeholder="Work Done /Activity done">
                        </div>

            <div class="d-flex mt-2">
                <div class="ms-auto">
                    <button type="button" class="btn btn-danger me-2"  @click="closeForm">Close</button>
                    <button type="submit" class="btn btn-primary" :disabled="loading">
                        <span v-if="loading" v-html="loadingSpinner()"></span>
                        <span v-else >Save</span>
                    </button>
                </div>
            </div>

                </div>
            </form>



</template>

<script setup>
import { ref, onMounted, watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect'
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css'
const loadingSpinner = inject('loadingSpinner')
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
const showMessage = inject('showMessage')
const showError = inject('showError')

const assets = ref([])
const group_id = ref(props.groupId)
const getAssets = async ()=>{
   const response = await axiosInstance.get(`machine-and-vehicles?group_id=${group_id.value}`)
   assets.value = response.data.map((item)=>({
     ...item,
     name : item.name + ' - '+ item.category
   }))
}

const formData = ref({
    id : '',
    asset : '',
    quantity : '',
    date : '',
    description : ''
})

const fillForm = ref(false)
const clearForm = ()=>{
    fillForm.value = false
    formData.value = {
    id : '',
    asset : '',
    quantity : '',
    date : '',
    description : '',

}
}

onMounted(() => {
 getAssets()
})



const props = defineProps({
    groupId: String,
    parentId : String,
    entryId : String,
    rateValue: Number
});


watch(() => props.groupId, (newId) => {
    if(newId){
        group_id.value = newId
        getAssets()
    }
})

const emit = defineEmits(["saved", "close"]);
const loading = ref(false)
const submitEntry = async ()=>{
    loading.value = true
    const payload = {
      entry_id : props.entryId,
      rate : props.rateValue,
      parent_id: props.parentId,
      quantity : formData.value.quantity,
      source : 'assets',
      source_id : formData.value.asset.id,
      date : formData.value.date,
      description : formData.value.description,
      unit_id:25
    }

     try{
         const response = await axiosInstance.post('entry-items',payload)
         showMessage('Data Saved')
             emit("saved")
         clearForm()
     }catch(error){
        showError(error.message)
        console.log(error)
     }finally{
       loading.value = false
     }
}

const closeForm = () => {
    clearForm()
    emit("close")
}

</script>