useMeta({ title: "Material Consumption" });
const add_entry = ref(false);
const showMessage = inject("showMessage");
const register_item_usage = ref(false);
const showError = inject("showError");
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const formatDate = inject("formatDate");
const formatNumber = inject("formatNumber");
const formatRate = inject("formatRate");
const enforceMax = inject("enforceMax");
const tableShimmer = inject("tableShimmer");
const waitIndicator = inject("waitIndicator");
const loadingSpinner = inject("loadingSpinner");
const register_expense = ref(false);
const user_id = JSON.parse(localStorage.getItem("user")).id;
const loading_spinner = ref(false);
const projectExpensesColumns = ref([
  "sno",
  "name",
  "quantity",
  "rate",
  "cost",
  "qty_used",
  "qty_balance",
  "amount_used",
  "action",
]);
const projectExpenseItemsColumns = ref([
  "sno",
   "date",
  "name",
  "quantity",
  "unit",
  "rate",
  "cost",
  "description"
]);

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 51, 100],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: ["SNo", "name", "short_name", "status"],
  sortIcon: {
    base: "sort-icon-none",
    up: "sort-icon-asc",
    down: "sort-icon-desc",
  },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const projectSearch = ref("");
const loadingProjects = ref(false);
const searchedProjects = computed(() => {
  if (!projectSearch.value) return projects.value;
  const q = projectSearch.value.toLowerCase();
  return projects.value.filter(
    (p) =>
      p.project_name?.toLowerCase().includes(q) || p.store_name?.toLowerCase().includes(q)
  );
});

const projectExpenses = ref([]);
const getProjectExpenses = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`project-expenses`, {
      params: {
        project_id: project.value?.project_id || "",
      },
    });
    projectExpenses.value = response.data.flatMap((entry) =>
      (entry.items || [])
        .filter((item) => item.parent_id === null)
        .map((item, index) => ({
          id: item.id,
          entry_id: entry.id,
          entry,
          ...item,
          sno: index + 1,
          name: item.item?.name,
          original_rate: item.rate,
          rate: formatRate(item.rate || "-"),
          cost: formatRate((item.rate || 0) * (item.quantity || 0)),
          qty_used: formatNumber(item.qty_used || 0),
          qty_balance: formatNumber(item.qty_balance || 0),
          amount_used: formatRate(item.amount_used || 0),
          unit: item.unit?.short_name || "-",
          quantity: item.quantity || 0,
          budget:
            entry.entry_relation?.find((relation) => relation.relation_name === "budgets")
              ?.budget?.name || "-",
          action: entry,
        }))
    );
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};

const projectExpenseItems = ref([]);
const getProjectExpenseItems = async (id) => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`project-expense-items`, {
      params: {
        parent_id: id || "",
      },
    });
    projectExpenseItems.value = response.data.map((item, index) => ({
      ...item,
      sno: index + 1,
      date : item.date || "--",
      description: item.description || "--",
      rate: formatRate(item.rate || "-"),
      cost: formatRate((item.rate || 0) * (item.quantity || 0)),
      name: item.item?.code + " - " + item.parent?.name,
      unit: item.unit?.short_name || "-",
      quantity: formatNumber(item.quantity || "-"),
    }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};

const projects = ref([]);
const project = ref(null);
const getProjects = async () => {
  try {
    const response = await axiosInstance.get("stores-projects");

    projects.value = response.data.map((item) => ({
      ...item,
    }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  }
};

const assetGroups = ref([]);
const featchingAssets = ref(false);
const getAssetGroups = async () => {
  featchingAssets.value = true;
  try {
    const response = await axiosInstance.get("asset-groups");

    assetGroups.value = response.data.map((item) => ({
      ...item,
    }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  }finally {
    featchingAssets.value = false;
  }
};

const project_expenses = ref(null);

const openViewModal = (row) => {
  console.log("Row data:", row); // Log the row data to the console for debugging
  project_expenses.value = row;
  // description.value = row.description;
  // date.value = row.date;
};

const name = ref("");
const asset_category = ref(null);
const quantity = ref("");
const rate = ref("");

const resetForm = () => {
  name.value = "";
  asset_category.value = null;
  quantity.value = "";
  rate.value = "";
  register_expense.value = false;

};

const loading = ref(false);
const registerProjectExpense = async () => {
  loading.value = true;
  const itemData = {
    source: "asset_groups",
    source_id: asset_category.value?.id || null,
    quantity: quantity.value,
    rate: rate.value,
    project_id: project.value?.project_id || null,
    issuer_id: user_id,
    asset_group: asset_category.value?.name || null,
  };

  console.log("Submitting item data:", itemData);

  try {
    const response = await axiosInstance.post("/store-project-expense", itemData);

    showMessage("submitted successfully!");
    getProjectExpenses();
    resetForm();
  } catch (error) {
    showError(error.message);
  } finally {
    loading.value = false;
  }
};

const closeModal = () => {
  project_expenses.value = null;
  add_entry.value = false;
};

const refreshExpenseItems = () => {
    if(project_expenses.value?.id){
        getProjectExpenseItems(project_expenses.value.id)
        add_entry.value = false;
    }
}

watch(project, () => {
  getProjectExpenses();
});


const printReport = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    // Helper to safely turn formatted strings (e.g. "12,345.00") back into numbers for totals
    const parseNum = (val) => {
      if (val === null || val === undefined) return 0;
      if (typeof val === "number") return val;
      const cleaned = String(val).replace(/,/g, "");
      const num = parseFloat(cleaned);
      return isNaN(num) ? 0 : num;
    };

    const rows = projectExpenses.value;

    const totals = rows.reduce(
      (acc, row) => {
        acc.quantity += parseNum(row.quantity);
        acc.cost += parseNum(row.cost);
        acc.qty_used += parseNum(row.qty_used);
        acc.qty_balance += parseNum(row.qty_balance);
        acc.amount_used += parseNum(row.amount_used);
        return acc;
      },
      { quantity: 0, cost: 0, qty_used: 0, qty_balance: 0, amount_used: 0 }
    );

    const printContent = `
