  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  .subtitle { text-align: center; font-size: 14px; margin: 4px 0 10px; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0px 0; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>

<div class="company-title text-style">
  <i>
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>

<hr style="margin-top:20px">

<div class="title text-style">
  PROJECT EXPENSES REPORT  ${project.value?.project_name || ""}
</div>

<hr>

<table>
  <thead>
    <tr>
      <th>No.</th>
      <th>Name</th>
      <th class="text-right">Quantity</th>
      <th class="text-right">Rate</th>
      <th class="text-right">Cost</th>
      <th class="text-right">Qty Used</th>
      <th class="text-right">Qty Balance</th>
      <th class="text-right">Amount Used</th>
    </tr>
  </thead>
  <tbody>
    ${rows.map((row, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${row.name || "N/A"}</td>
      <td class="text-right">${formatNumber(row.quantity || 0)}</td>
      <td class="text-right">${row.rate || "-"}</td>
      <td class="text-right">${row.cost || "-"}</td>
      <td class="text-right">${row.qty_used || "-"}</td>
      <td class="text-right">${row.qty_balance || "-"}</td>
      <td class="text-right">${row.amount_used || "-"}</td>
    </tr>
    `).join("")}
    <tr>
      <td colspan="2" class="text-right"><strong>TOTAL:</strong></td>
      <td class="text-right"><strong>${formatNumber(totals.quantity)}</strong></td>
      <td class="text-right">-</td>
      <td class="text-right"><strong>${formatRate(totals.cost)}</strong></td>
      <td class="text-right"><strong>${formatNumber(totals.qty_used)}</strong></td>
      <td class="text-right"><strong>${formatNumber(totals.qty_balance)}</strong></td>
      <td class="text-right"><strong>${formatRate(totals.amount_used)}</strong></td>
    </tr>
  </tbody>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};

const printItemsReport = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const parseNum = (val) => {
      if (val === null || val === undefined) return 0;
      if (typeof val === "number") return val;
      const cleaned = String(val).replace(/,/g, "");
      const num = parseFloat(cleaned);
      return isNaN(num) ? 0 : num;
    };

    const rows = projectExpenseItems.value;

